 const importInstagramFolder=async(files:File[])=>{try{const batch='ig-'+Date.now(),own=[localStorage.getItem('memento.instagramUsername')||'',localStorage.getItem('memento.instagramDisplayName')||'',username,displayName];const chats=await parseInstagramFiles(files,batch,own,(file,id)=>storeAttachment(id,file));if(!chats.length)throw new Error('No message_N.json files found. Choose the inbox folder itself.');setImportedChats(all=>[...all,...chats]);setChatImportHistory(all=>[{id:batch,platform:'instagram',importedAt:Date.now(),count:chats.length},...all]);window.alert('Imported '+chats.length+' Instagram conversations.')}catch(e){window.alert(e instanceof Error?e.message:'Instagram import failed.')}}
